-- Disposable metadata baseline; no new production table.
create table private.vt_ci_baseline as select (select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.member_permissions'::regclass and contype='c') permission_check,(select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.saved_views'::regclass and conname='saved_views_object_type_check') view_check,(select md5(coalesce(jsonb_agg(to_jsonb(v) order by id)::text,'')) from public.saved_views v) view_hash,(select relacl::text from pg_class where oid='public.saved_views'::regclass) view_grants,(select relacl::text from pg_class where oid='public.crm_board_item_checklist_items'::regclass) checklist_grants;
